/**
 * The third shipped build, where the game restated three of its tables rather than changing them.
 *
 * The 1650 build moved the item-kind enum into the same chunk as the art tables, stopped writing an explicit
 * over-mutation set, and stopped deriving an icon share from a `sizeRatio` default: the icon box is now scaled by
 * a function that states the share per kind. The tables are the same seven kinds and the same shares, so the
 * extractor has to read the new spellings without the model learning a new value.
 *
 * The fixture is generated by `art:sync --bundle` from the capture of the game's own chunks, so this file
 * measures the shipped path and not a hand-written echo of it.
 */

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mutationStack } from '../../src/mutation.ts';
import { loadFixture, shippedFixtureDirectory } from './load-fixture.ts';

const fixture = loadFixture(shippedFixtureDirectory('1650'));
const { tables } = fixture;

void test('the icon shares are the same seven, stated by the multiplier switch instead of a 256 frame', () => {
  assert.deepEqual(tables.iconFills, {
    Seed: { fill: 1, source: 'fit-default' },
    Produce: { fill: 0.4, source: 'stated' },
    Plant: { fill: 0.6, source: 'stated' },
    Tool: { fill: 1, source: 'fit-default' },
    Pet: { fill: 1, source: 'bake-frame' },
    Egg: { fill: 1, source: 'fit-default' },
    Decor: { fill: 1, source: 'fit-default' },
  });
});

void test('the z-index is the 1650 ladder, not the 1192 marker', () => {
  const stackOf = (name: string) =>
    mutationStack({ ...tables.mutationArt[name], name }, tables.overMutations);
  assert.deepEqual(
    {
      wet: stackOf('Wet').zIndex,
      wetTall: stackOf('Wet').tallPlantZIndex,
      dawnlit: stackOf('Dawnlit').zIndex,
      dawnlitTall: stackOf('Dawnlit').tallPlantZIndex,
      gold: stackOf('Gold').zIndex,
      goldTall: stackOf('Gold').tallPlantZIndex,
    },
    { wet: 2, wetTall: -1, dawnlit: 4, dawnlitTall: 4, gold: 0, goldTall: 0 },
  );
});

void test('the over-mutations are the classes the z-ladder draws above the crop body', () => {
  assert.deepEqual([...tables.overMutations].sort(), [
    'Ambercharged',
    'Ambershine',
    'Chilled',
    'Dawncharged',
    'Dawnlit',
    'Frozen',
    'Thundercharged',
    'Thunderstruck',
    'Wet',
  ]);
});

void test('the crop and produce schemas state the new carving fields', () => {
  const crop = tables.kindSchemas.arms[tables.kindSchemas.crops[0] ?? ''];
  assert.ok(crop !== undefined, 'the crop schema was not recorded');
  const cropFields = new Set(crop.fields.map((field) => field.name));
  for (const field of ['locked', 'carving', 'carvingVerdict']) {
    assert.ok(cropFields.has(field), `the crop schema states no ${field}`);
  }

  const produceId = tables.kindSchemas.items['Produce']?.[0];
  assert.ok(produceId !== undefined, 'the item union states no Produce arm');
  const produce = tables.kindSchemas.arms[produceId];
  assert.ok(produce !== undefined, 'the Produce arm was not recorded');
  const produceFields = new Set(produce.fields.map((field) => field.name));
  for (const field of ['carving', 'carvingVerdict']) {
    assert.ok(produceFields.has(field), `the Produce schema states no ${field}`);
  }
  assert.equal(
    produce.fields.find((field) => field.name === 'carving')?.required,
    false,
    'the Produce carving field is not optional',
  );
});

void test('the item and tile enums are still exactly the kinds the schemas declare', () => {
  assert.deepEqual(tables.itemTypes, {
    Seed: 'Seed',
    Produce: 'Produce',
    Plant: 'Plant',
    Tool: 'Tool',
    Pet: 'Pet',
    Egg: 'Egg',
    Decor: 'Decor',
  });
  assert.deepEqual(tables.kindSchemas.tileTypes, {
    Plant: 'plant',
    Egg: 'egg',
    Decor: 'decor',
    Crystal: 'crystal',
  });
});
